"use client";

import React, { useState } from "react";
import {
  ShieldCheck,
  Copy,
  Check,
  Eye,
  EyeOff,
  Download,
  Clock,
  ExternalLink,
  MessageSquare,
  CheckCircle2,
  Loader2,
} from "lucide-react";
import { AnimatedModal } from "@/components/ui/modal";

export interface CredentialUnit {
  id?: string | number;
  unitId?: string | number;
  plaintext?: string;
  payload?: string;
  formatted?: string;
  email?: string | null;
  password?: string | null;
  twoFactorSecret?: string | null;
  notes?: string | null;
  profileName?: string | null;
  profilePin?: string | null;
}

export interface CredentialRevealModalProps {
  isOpen: boolean;
  onClose: () => void;
  orderCode: string;
  productName: string;
  units: CredentialUnit[];
  warrantyExpiresAt?: string | null;
  warrantyActive?: boolean;
  isLoading?: boolean;
}

export function CredentialRevealModal({
  isOpen,
  onClose,
  orderCode,
  productName,
  units,
  warrantyExpiresAt,
  warrantyActive = true,
  isLoading = false,
}: CredentialRevealModalProps) {
  const [showPasswords, setShowPasswords] = useState<Record<number, boolean>>({});
  const [copiedAll, setCopiedAll] = useState(false);
  const [copiedIndex, setCopiedIndex] = useState<number | null>(null);

  // Toggle single unit password mask
  const toggleShowPassword = (idx: number) => {
    setShowPasswords((prev) => ({ ...prev, [idx]: !prev[idx] }));
  };

  // Helper to extract clean email and password from raw string or unit object
  const parseUnit = (u: CredentialUnit) => {
    let email = u.email || "";
    let password = u.password || "";
    let raw = u.plaintext || u.payload || u.formatted || "";

    const isLink =
      (u as any).type === "LINK" ||

